      ctx,
    );
  const top = git(projectRoot, ["rev-parse", "--show-toplevel"]);
  if (!top.ok) throw headUnreadable(top.err || "not a git repository");
  const toplevel = top.out.trim();
  const head = git(toplevel, ["rev-parse", "--verify", "--quiet", "HEAD^{commit}"]);
